namespace {constexpr double Pi=3.14159265358979323846;float Lerp(float a,float b,float t){return a+(b-a)*t;}float Angle(float a,float b){float d=std::fmod(b-a,360.f);if(d>180)d-=360;if(d< -180)d+=360;return d;}uint32_t Read(const uint8_t*p){return uint32_t(p[0])|uint32_t(p[1])<<8|uint32_t(p[2])<<16|uint32_t(p[3])<<24;}float Hash(uint32_t x,uint32_t y){uint32_t h=x*374761393u+y*668265263u;h=(h^(h>>13))*1274126177u;h^=h>>16;return float(h&0xffffffu)/float(0xffffffu);}float Noise(double x,double y){double ix=std::floor(x),iy=std::floor(y);if(!std::isfinite(ix)||!std::isfinite(iy)||std::abs(ix)>1e12||std::abs(iy)>1e12)return .5f;uint32_t a=uint32_t(int64_t(ix)),b=uint32_t(int64_t(iy));float tx=SmoothStep(float(x-ix)),ty=SmoothStep(float(y-iy));return Lerp(Lerp(Hash(a,b),Hash(a+1,b),tx),Lerp(Hash(a,b+1),Hash(a+1,b+1),tx),ty);}float Fbm(double x,double y){return .55f*Noise(x,y)+.3f*Noise(x*2.1+7.3,y*2.1-3.1)+.15f*Noise(x*4.3-1.7,y*4.3+5.9);}float Dist2(V3 a,V3 b){float x=a.x-b.x,y=a.y-b.y,z=a.z-b.z;return x*x+y*y+z*z;}bool MatchPlace(const Cdbc&t,uint32_t r,int scope,int id){return t.U32(r,1)==uint32_t(scope)&&(scope==0||t.U32(r,2)==uint32_t(id));}}
float Saturate(float x){return std::isfinite(x)?std::clamp(x,0.f,1.f):0;}
float SmoothStep(float x){x=Saturate(x);return x*x*(3-2*x);}bool Finite(V3 x){return std::isfinite(x.x)&&std::isfinite(x.y)&&std::isfinite(x.z);}
bool Cdbc::Load(const char*path){std::ifstream f(path,std::ios::binary|std::ios::ate);auto n=f.tellg();if(!f||n<20||n>64*1024*1024){bytes_.clear();rows_=columns_=0;error_="file missing or size outside limits";return false;}std::vector<uint8_t>b(size_t(n),0);f.seekg(0);if(!f.read(reinterpret_cast<char*>(b.data()),n)){bytes_.clear();rows_=columns_=0;error_="short read";return false;}return Parse(b.data(),b.size());}
bool Cdbc::Parse(const void*data,size_t size){bytes_.clear();rows_=columns_=stride_=strings_=0;error_="invalid WDBC";if(!data||size<20||size>64*1024*1024)return false;auto*p=(const uint8_t*)data;if(std::memcmp(p,"WDBC",4))return false;uint32_t n=Read(p+4),c=Read(p+8),s=Read(p+12),str=Read(p+16);if(!c||c>1024||s!=uint64_t(c)*4||!str||20ull+uint64_t(n)*s+str!=size||p[size-1])return false;for(uint32_t r=1;r<n;++r)if(Read(p+20+size_t(r)*s)<=Read(p+20+size_t(r-1)*s)){error_="duplicate or unsorted row ID";return false;}bytes_.assign(p,p+size);rows_=n;columns_=c;stride_=s;strings_=str;error_.clear();return true;}
uint32_t Cdbc::U32(uint32_t r,uint32_t c,uint32_t fallback)const{return r<rows_&&c<columns_?Read(bytes_.data()+20+size_t(r)*stride_+size_t(c)*4):fallback;}
float Cdbc::F32(uint32_t r,uint32_t c,float fallback)const{if(r>=rows_||c>=columns_)return fallback;uint32_t u=U32(r,c);float f;std::memcpy(&f,&u,4);return std::isfinite(f)?f:fallback;}
const char*Cdbc::Text(uint32_t r,uint32_t c)const{uint32_t p=U32(r,c,~0u);return p<strings_?reinterpret_cast<const char*>(bytes_.data()+20+size_t(rows_)*stride_+p):"";}
DensityValues ResolveDensity(const Cdbc&t,const Place&p,uint32_t doodad,uint32_t effect){float v[3]={-1,-1,-1};if(t.Columns()<8||p.areaCount>16)return{};auto apply=[&](int scope,int id){for(int level=0;level<4;++level)for(uint32_t r=0;r<t.Rows();++r){if(!MatchPlace(t,r,scope,id))continue;uint32_t d=t.U32(r,3),e=t.U32(r,4);bool what=level==0?(d&&e&&d==doodad&&e==effect):level==1?(d&&!e&&d==doodad):level==2?(!d&&e&&e==effect):(!d&&!e);if(!what)continue;for(int k=0;k<3;++k){float x=t.F32(r,5+k,-1);if(v[k]<0&&x>=0)v[k]=x;}break;}};for(uint32_t i=0;i<p.areaCount;++i)apply(2,int(p.areas[i]));if(p.map>=0)apply(1,p.map);apply(0,0);DensityValues out;if(v[0]>=0)out.multiplier=v[0];if(v[1]>=0)out.radius=v[1];if(v[2]>=0)out.spread=v[2];return out;}
DensityValues CapDensity(DensityValues v,float m,float r,float s){v.multiplier=std::clamp(std::isfinite(v.multiplier)?v.multiplier:1.f,1.f,std::clamp(std::isfinite(m)?m:1.f,1.f,8.f));v.radius=std::clamp(std::isfinite(v.radius)?v.radius:0.f,0.f,std::max(0.f,std::isfinite(r)?r:0.f));v.spread=std::clamp(std::isfinite(v.spread)?v.spread:0.f,0.f,std::max(0.f,std::isfinite(s)?s:0.f));return v;}
float ThinShare(float d,float start,float end,float minimum){if(!std::isfinite(d)||!std::isfinite(start)||!std::isfinite(end))return 1;minimum=std::clamp(std::isfinite(minimum)?minimum:1.f,.01f,1.f);if(d<=start)return 1;if(d>=end||end<=start)return minimum;return Lerp(1,minimum,(d-start)/(end-start));}
uint32_t ThinCount(uint32_t n,float share){return std::min(n,uint32_t(std::ceil(double(n)*Saturate(share))));}
uint32_t DensityCopies(float m){return uint32_t(std::clamp(std::isfinite(m)?std::floor(m+.5f):1.f,1.f,8.f));}
uint32_t CopiesAtDistance(DensityValues v,float distance,bool valid){if(!valid||!std::isfinite(distance)||v.multiplier<1.5f||v.radius<=1)return 1;float full=v.radius*.5f;float t=distance<=full?1:distance>=v.radius?0:1-(distance-full)/(v.radius-full);return DensityCopies(1+(v.multiplier-1)*t);}
RootMapping AnalyzeRoots(const MeshPoint*v,size_t count,const uint16_t*ix,size_t n){RootMapping out;if(!v||!ix||!count||count>65536||!n||n>200000)return out;float lo=1e30f,hi=-1e30f;for(size_t i=0;i<n;++i){if(ix[i]>=count||!Finite(v[ix[i]].position)||!std::isfinite(v[ix[i]].v))return out;lo=std::min(lo,v[ix[i]].position.z);hi=std::max(hi,v[ix[i]].position.z);}out.height=hi-lo;double a=0,b=0;size_t an=0,bn=0;float band=out.height*.12f;for(size_t i=0;i<n;++i){const auto&p=v[ix[i]];if(p.position.z<=lo+band){a+=p.v;++an;}if(p.position.z>=hi-band){b+=p.v;++bn;}}if(!an||!bn)return out;out.rootV=float(a/an);float tip=float(b/bn);out.flat=out.height<.15f;out.valid=std::abs(tip-out.rootV)>.01f||out.flat;out.inverseSpan=std::abs(tip-out.rootV)>.01f?1/(tip-out.rootV):0;if(out.flat)out.wind=out.push=0;return out;}
float BendWeight(float v,V4 mapping,float anchor){float base=Saturate((v-mapping.x)*mapping.y);anchor=std::clamp(std::isfinite(anchor)?anchor:.15f,0.f,.9f);float w=Saturate((base-anchor)/(1-anchor));return w*w;}
uint32_t SelectActors(const Actor*input,size_t n,V3 player,std::array<V4,16>&out,float radiusScale,float mountedScale,float minimum){out={};if(!input||!Finite(player)||n>4096)return 0;std::array<float,16>d{};std::array<uint64_t,16>key{};d.fill(1e30f);uint32_t count=0;for(size_t i=0;i<n;++i){auto&a=input[i];if(!Finite(a.position)||!std::isfinite(a.radius)||a.radius<0)continue;float ds=Dist2(a.position,player);if(!std::isfinite(ds)||ds>40*40)continue;bool duplicate=false;for(uint32_t k=0;k<count;++k)if(a.key&&key[k]==a.key)duplicate=true;if(duplicate)continue;size_t at=0;while(at<count&&(d[at]<ds||(d[at]==ds&&key[at]<a.key)))++at;if(at>=16)continue;for(size_t k=std::min<uint32_t>(count,15);k>at;--k){out[k]=out[k-1];d[k]=d[k-1];key[k]=key[k-1];}float r=std::max(minimum,a.radius*radiusScale*(a.mounted?mountedScale:1));if(!std::isfinite(r))r=minimum;out[at]={a.position.x,a.position.y,a.position.z,std::clamp(r,0.f,100.f)};d[at]=ds;key[at]=a.key;count=std::min(count+1,16u);}return count;}
WindProfile ResolveWind(const Cdbc&t,const Place&p){WindProfile out;if(t.Columns()<14||p.areaCount>16)return out;auto apply=[&](int scope,int id){for(uint32_t r=0;r<t.Rows();++r)if(MatchPlace(t,r,scope,id)){for(int f=0;f<WindFields;++f){float x=t.F32(r,3+f,-1);if(x>=0)out.p[f]=x;}break;}};apply(0,0);if(p.map>=0)apply(1,p.map);for(uint32_t i=p.areaCount;i>0;--i)apply(2,int(p.areas[i-1]));return out;}
void WindModel::Reset(){*this=WindModel{};}
void WindModel::Update(const WindProfile&target,int map,float weather,double seconds,double dt){if(!std::isfinite(seconds))return;dt=std::isfinite(dt)?std::clamp(dt,0.,.25):0.;if(!initialized_||map!=map_||seconds<seconds_){current_=target;initialized_=true;}else{float k=float(1-std::exp(-dt/1.5));for(int f=0;f<WindFields;++f){float v=std::isfinite(target.p[f])?target.p[f]:0;current_.p[f]=f==LockedDirection?current_.p[f]+Angle(current_.p[f],v)*k:Lerp(current_.p[f],v,k);}}for(auto&v:current_.p)if(!std::isfinite(v))v=0;map_=map;seconds_=seconds;auto*p=current_.p;float where=.2f+.5f*Noise(seconds/40+17.3,0);where+=(1-where)*Saturate(weather*p[WeatherInfluence]);ground_=Lerp(p[GroundMin],p[GroundMax],where);aloft_=Lerp(p[AloftMin],p[AloftMax],where);bearing_=Hash(uint32_t(map),91)*360+60*(Noise(seconds/90+3.1,0)*2-1);bearing_+=Angle(bearing_,p[LockedDirection])*Saturate(p[LockStrength]);bearing_=std::fmod(bearing_+360,360.f);}
WindSample WindModel::At(V3 p,float open,float lee,float height)const{if(!initialized_||!Finite(p))return{};auto*v=current_.p;float steady=Lerp(ground_,aloft_,v[AloftHeight]>0?Saturate(height/v[AloftHeight]):0);double a=bearing_*Pi/180,dx=std::cos(a),dy=-std::sin(a),along=double(p.x)*dx+double(p.y)*dy,across=-double(p.x)*dy+double(p.y)*dx;double freq=std::max(.05f,v[GustFrequency]),speed=4+16*steady;float gust=Saturate((Fbm((along-seconds_*speed)/(50/freq),across/(35/freq))-.5f)*3);double veer=(Noise((along-seconds_*speed)/80+31,across/80)-.5)*20*(.5+gust)*Pi/180;float strength=steady*(1+v[GustStrength]*gust)*Saturate(open)*Saturate(lee);return{float((dx*std::cos(veer)-dy*std::sin(veer))*strength),float((dx*std::sin(veer)+dy*std::cos(veer))*strength),gust};}
void BuildGrid(const WindModel&m,V3 p,double seconds,float speed,MotionBlock&b,const float*open,const float*lee){if(!Finite(p)||!std::isfinite(seconds)||std::abs(p.x)>1000000||std::abs(p.y)>1000000)return;int x=int(std::floor(p.x/8))-4,y=int(std::floor(p.y/8))-4;double phase=std::remainder(seconds*speed,2*Pi);b.gridInfo={x+.5f,y+.5f,.125f,float(phase)};b.player={p.x,p.y,p.z,2025};for(int j=0;j<8;++j)for(int i=0;i<8;++i){int k=j*8+i;auto s=m.At({(x+i+.5f)*8,(y+j+.5f)*8,p.z},open?open[k]:1,lee?lee[k]:1);b.grid[k]={s.x,s.y,s.gust,0};}}
V3 EvaluateMotion(const MotionBlock&b,V3 p,float uv,V4 mapping,V3 legacyWind,V3 legacyActors,float weight){bool wind=b.options.x>.5f,actors=b.options.y>.5f,roots=b.options.z>.5f;if(!wind&&!actors&&!roots)return{(legacyWind.x+legacyActors.x)*weight,(legacyWind.y+legacyActors.y)*weight,(legacyWind.z+legacyActors.z)*weight};V3 w=legacyWind,a=legacyActors;if(wind){float qx=std::clamp(p.x*b.gridInfo.z-b.gridInfo.x,0.f,6.999f),qy=std::clamp(p.y*b.gridInfo.z-b.gridInfo.y,0.f,6.999f);int x=int(qx),y=int(qy);float tx=qx-x,ty=qy-y;auto sample=[&](int c){auto r=[&](int i){auto&v=b.grid[i];return c==0?v.x:c==1?v.y:v.z;};return Lerp(Lerp(r(y*8+x),r(y*8+x+1),tx),Lerp(r((y+1)*8+x),r((y+1)*8+x+1),tx),ty);};float flutter=std::cos(b.gridInfo.w+p.x*.61f+p.y*.37f)*(sample(2)+.3f)*b.sway.y;float gain=b.sway.x+flutter;w={sample(0)*gain,sample(1)*gain,0};}if(actors){a={};if((p.x-b.player.x)*(p.x-b.player.x)+(p.y-b.player.y)*(p.y-b.player.y)<b.player.w){unsigned n=uint32_t(std::clamp(b.options.w,0.f,16.f));for(unsigned i=0;i<n;++i){auto&v=b.actors[i];if(v.w<=0||!std::isfinite(v.w))continue;float dx=p.x-v.x,dy=p.y-v.y,d2=dx*dx+dy*dy+.001f,inv=1/std::sqrt(d2),dist=d2*inv;float push=std::max(1-dist/v.w,0.f)*Saturate(3-std::abs(p.z-v.z))*inv;a.x+=dx*push;a.y+=dy*push;}a.x*=b.sway.z;a.y*=b.sway.z;}}if(roots){weight=BendWeight(uv,mapping,b.sway.w);w.x*=mapping.z;w.y*=mapping.z;w.z*=mapping.z;a.x*=mapping.w;a.y*=mapping.w;a.z*=mapping.w;}return{(w.x+a.x)*weight,(w.y+a.y)*weight,(w.z+a.z)*weight};}
void GridHistory::Reset(){for(auto&c:cells_)c.valid=false;map_=-1;seconds_=-1;}
void GridHistory::Apply(MotionBlock&b,int map,double seconds,double dt){if(!std::isfinite(seconds)||!std::isfinite(b.gridInfo.x)||!std::isfinite(b.gridInfo.y)||std::abs(b.gridInfo.x)>1000000||std::abs(b.gridInfo.y)>1000000)return;if(map!=map_||seconds<seconds_||seconds_-seconds< -1)Reset();float ease=float(1-std::exp(-std::clamp(std::isfinite(dt)?dt:0.,0.,.25)/.35));int bx=int(std::floor(b.gridInfo.x)),by=int(std::floor(b.gridInfo.y));for(int j=0;j<8;++j)for(int i=0;i<8;++i){int x=bx+i,y=by+j;auto&c=cells_[(uint32_t(y)&15u)*16+(uint32_t(x)&15u)];auto target=b.grid[j*8+i];if(!c.valid||c.x!=x||c.y!=y){c.value=target;c.x=x;c.y=y;c.valid=true;}else{c.value.x=Lerp(c.value.x,target.x,ease);c.value.y=Lerp(c.value.y,target.y,ease);c.value.z=Lerp(c.value.z,target.z,ease);}b.grid[j*8+i]=c.value;}map_=map;seconds_=seconds;}
bool SameBatch(const BatchKey&a,const BatchKey&b){return a.texture==b.texture&&a.model==b.model&&a.material==b.material&&a.pipeline==b.pipeline&&a.page==b.page&&a.shadowVariant==b.shadowVariant&&a.flags==b.flags;}
size_t PlanBatches(const DrawRange*in,size_t n,DrawRange*out,size_t capacity,uint32_t maxRanges){if((n&&(!in||!out))||n>capacity||!maxRanges)return size_t(-1);for(size_t i=0;i<n;++i)out[i]=in[i];auto less=[](const DrawRange&a,const DrawRange&b){return std::tie(a.key.texture,a.key.model,a.key.material,a.key.pipeline,a.key.page,a.key.shadowVariant,a.key.flags)<std::tie(b.key.texture,b.key.model,b.key.material,b.key.pipeline,b.key.page,b.key.shadowVariant,b.key.flags);};bool ordered=false;for(size_t i=0;i<n;++i)ordered|=(out[i].key.flags&1)!=0;if(!ordered&&n)std::sort(out,out+n,less);size_t batches=0,ranges=0;BatchKey key{};for(size_t i=0;i<n;++i){if(!out[i].count)continue;if(!ranges||!SameBatch(key,out[i].key)||ranges==maxRanges){++batches;ranges=0;key=out[i].key;}++ranges;}return batches;}
bool SameCache(const CacheKey&a,const CacheKey&b){return a.sceneEpoch==b.sceneEpoch&&a.stableModel==b.stableModel&&a.placementGeneration==b.placementGeneration&&a.materialGeneration==b.materialGeneration&&a.densityGeneration==b.densityGeneration&&a.formatVersion==b.formatVersion;}
void Budget::Begin(double now,double limit,size_t bytes,size_t max){start_=now;limit_=std::isfinite(limit)?std::max(0.,limit):0;bytes_=bytes;max_=max;}
bool Budget::CanBuild(double now,size_t size)const{return std::isfinite(now)&&now>=start_&&now-start_<limit_&&bytes_<=max_&&size<=max_-bytes_;}
